import{_ as e,o as a,c as i,a4 as o}from"./chunks/framework.DPwo9VAo.js";const g=JSON.parse('{"title":"Tra cứu API: Classes (Lớp đối tượng)","description":"","frontmatter":{},"headers":[],"relativePath":"api-reference/classes.md","filePath":"api-reference/classes.md","lastUpdated":1795338762000}'),d={name:"api-reference/classes.md"};function c(l,t,n,s,r,h){return a(),i("div",null,t[0]||(t[0]=[o('<h1 id="tra-cuu-api-classes-lop-đoi-tuong" tabindex="-1">Tra cứu API: Classes (Lớp đối tượng) <a class="header-anchor" href="#tra-cuu-api-classes-lop-đoi-tuong" aria-label="Permalink to &quot;Tra cứu API: Classes (Lớp đối tượng)&quot;">​</a></h1><p>Tài liệu này mô tả chi tiết các Class quan trọng trong thư viện, bao gồm mục đích, constructor, phương thức và ví dụ thực tế.</p><hr><h2 id="_1-mapinitializer-hungpvq-map-core" tabindex="-1">1. <code>MapInitializer</code> (<code>@hungpvq/map-core</code>) <a class="header-anchor" href="#_1-mapinitializer-hungpvq-map-core" aria-label="Permalink to &quot;1. `MapInitializer` (`@hungpvq/map-core`)&quot;">​</a></h2><p>Class tiện ích tĩnh (static class) cung cấp các phương thức chuẩn hóa việc khởi tạo và dọn dẹp MapLibre instance.</p><h3 id="static-methods" tabindex="-1">Static Methods: <a class="header-anchor" href="#static-methods" aria-label="Permalink to &quot;Static Methods:&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Tên phương thức</th><th style="text-align:left;">Tham số</th><th style="text-align:left;">Giá trị trả về</th><th style="text-align:left;">Mô tả</th></tr></thead><tbody><tr><td style="text-align:left;"><code>isWebglSupported()</code></td><td style="text-align:left;">Không</td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;">Kiểm tra trình duyệt có hỗ trợ WebGL 1.0 hoặc 2.0 hay không</td></tr><tr><td style="text-align:left;"><code>validateWebglSupport(mapId)</code></td><td style="text-align:left;"><code>mapId: string</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">Ném ra lỗi <code>MapInitializationError</code> nếu WebGL bị vô hiệu hóa</td></tr><tr><td style="text-align:left;"><code>createDefaultOptions(customOptions?)</code></td><td style="text-align:left;"><code>customOptions?: Partial&lt;MapOptions&gt;</code></td><td style="text-align:left;"><code>Partial&lt;MapOptions&gt;</code></td><td style="text-align:left;">Tạo đối tượng MapOptions với các giá trị mặc định tối ưu (center Việt Nam, attribution false, zoom 5.3)</td></tr><tr><td style="text-align:left;"><code>createMapStyle(customStyle?)</code></td><td style="text-align:left;"><code>customStyle?: Partial&lt;Style&gt;</code></td><td style="text-align:left;"><code>object</code></td><td style="text-align:left;">Tạo Style JSON rỗng chuẩn (version 8, demotiles glyphs)</td></tr><tr><td style="text-align:left;"><code>setupMapEvents(map, callbacks)</code></td><td style="text-align:left;"><code>map: MapSimple</code>, <code>callbacks: MapEventCallbacks</code></td><td style="text-align:left;"><code>() =&gt; void</code></td><td style="text-align:left;">Gắn sự kiện <code>load</code> và <code>error</code> chuẩn hóa, trả về hàm cleanup</td></tr><tr><td style="text-align:left;"><code>cleanupMap(map, callbacks?)</code></td><td style="text-align:left;"><code>map: MapSimple</code>, <code>callbacks?: MapEventCallbacks</code></td><td style="text-align:left;"><code>void</code></td><td style="text-align:left;">Thực thi callback onDestroy và gọi <code>map.remove()</code></td></tr></tbody></table><hr><h2 id="_2-mapstoremanager-hungpvq-map-core" tabindex="-1">2. <code>MapStoreManager</code> (<code>@hungpvq/map-core</code>) <a class="header-anchor" href="#_2-mapstoremanager-hungpvq-map-core" aria-label="Permalink to &quot;2. `MapStoreManager` (`@hungpvq/map-core`)&quot;">​</a></h2><p>Singleton quản lý các store trạng thái phân tầng theo từng <code>mapId</code>.</p><h3 id="methods" tabindex="-1">Methods: <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods:&quot;">​</a></h3><ul><li><code>getStore(mapId: string): MapStore</code>: Lấy store gốc của bản đồ.</li><li><code>subscribeMapReady(mapId: string, cb: (map: MapSimple) =&gt; void): () =&gt; void</code>: Đăng ký callback khi map sẵn sàng.</li><li><code>clearMapStore(mapId: string): void</code>: Xóa bỏ toàn bộ dữ liệu store khi hủy bản đồ.</li></ul><hr><h2 id="_3-universalregistry-hungpvq-map-core" tabindex="-1">3. <code>UniversalRegistry</code> (<code>@hungpvq/map-core</code>) <a class="header-anchor" href="#_3-universalregistry-hungpvq-map-core" aria-label="Permalink to &quot;3. `UniversalRegistry` (`@hungpvq/map-core`)&quot;">​</a></h2><p>Điểm lưu trữ và phân phối các tiện ích mở rộng (Plugin / Extension registry).</p><h3 id="static-methods-1" tabindex="-1">Static Methods: <a class="header-anchor" href="#static-methods-1" aria-label="Permalink to &quot;Static Methods:&quot;">​</a></h3><ul><li><code>register&lt;T&gt;(namespace: RegistryNamespaceKind, key: string, value: T): void</code>: Đăng ký một giá trị vào namespace (<code>control</code>, <code>menu</code>, <code>format</code>).</li><li><code>get&lt;T&gt;(namespace: RegistryNamespaceKind, key: string): T | undefined</code>: Lấy giá trị đã đăng ký.</li><li><code>list(namespace: RegistryNamespaceKind): string[]</code>: Liệt kê tất cả các key thuộc namespace.</li><li><code>unregister(namespace: RegistryNamespaceKind, key: string): void</code>: Hủy đăng ký.</li></ul><hr><h2 id="_4-datasetservice-hungpvq-map-dataset" tabindex="-1">4. <code>DatasetService</code> (<code>@hungpvq/map-dataset</code>) <a class="header-anchor" href="#_4-datasetservice-hungpvq-map-dataset" aria-label="Permalink to &quot;4. `DatasetService` (`@hungpvq/map-dataset`)&quot;">​</a></h2><p>Lớp dịch vụ trung tâm điều phối nạp, xóa và đồng bộ hóa cây dữ liệu trên bản đồ.</p><h3 id="methods-1" tabindex="-1">Methods: <a class="header-anchor" href="#methods-1" aria-label="Permalink to &quot;Methods:&quot;">​</a></h3><ul><li><code>register(dataset: IDataset): void</code>: Đăng ký dataset vào store.</li><li><code>unregister(datasetId: string): void</code>: Gỡ bỏ dataset khỏi store.</li><li><code>getDataset(datasetId: string): IDataset | undefined</code>: Truy vấn dataset theo id.</li><li><code>findDatasetByLayerId(layerId: string): IDataset | undefined</code>: Tìm kiếm dataset sở hữu layer tương ứng trên MapLibre.</li></ul><hr><h2 id="_5-drawservice-hungpvq-map-draw" tabindex="-1">5. <code>DrawService</code> (<code>@hungpvq/map-draw</code>) <a class="header-anchor" href="#_5-drawservice-hungpvq-map-draw" aria-label="Permalink to &quot;5. `DrawService` (`@hungpvq/map-draw`)&quot;">​</a></h2><p>Lớp điều khiển tương tác vẽ và chỉnh sửa hình học không gian dựa trên Mapbox GL Draw.</p><h3 id="constructor" tabindex="-1">Constructor: <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor:&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DrawService</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(map: MapSimple, options</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MapDrawOptions)</span></span></code></pre></div><h3 id="methods-2" tabindex="-1">Methods: <a class="header-anchor" href="#methods-2" aria-label="Permalink to &quot;Methods:&quot;">​</a></h3><ul><li><code>startDraw(type: DrawingType, callback: (feat: Feature) =&gt; void): void</code>: Bật chế độ vẽ một hình học cụ thể (Point, LineString, Polygon, Circle, Rectangle).</li><li><code>stopDraw(): void</code>: Dừng chế độ vẽ và trả con trỏ chuột về mặc định.</li><li><code>deleteAll(): void</code>: Xóa toàn bộ các đối tượng đang vẽ tạm trên bản đồ.</li><li><code>getSelected(): Feature[]</code>: Lấy danh sách các đối tượng đang được chọn.</li><li><code>setFeatures(fc: FeatureCollection): void</code>: Nạp một FeatureCollection vào phiên làm việc của công cụ vẽ.</li></ul>',29)]))}const u=e(d,[["render",c]]);export{g as __pageData,u as default};
